from pathlib import Path
import json,hashlib,base64,os,sys,subprocess,time
S=Path('/dataset/shaoshitong/search-r1-rl/bapo-fresh200-behavior-20261006');R=S/'evidence-first5-behavior-v1'
assert not sys.flags.optimize and os.uname().nodename=='h100-5' and (S/'source-expected.txt').read_text().strip()=='90755a561abd239fbb23882939410e643bb913ae'
files={'first5_helpers.py': {'data': '', 'sha256': '53a924d0d41711c9c949e4638ddc7cc1d6bc8b21f751b5b284003629420073bd'}, 'first5-extract.py': {'data': '', 'sha256': 'bbfbaab0b15b6fe51a559e155698f095e702b71efc814ae4cf829c9f2b7f2773'}, 'first5-hf.py': {'data': '', 'sha256': 'e60004c170a828c3809ec583b3ea694230e550f16f43e794da42cbfcdc886bee'}, 'publish-first5-release.CANDIDATE.py': {'data': '', 'sha256': 'd2ed9a019e16a8e4e6297f99241226087c54e0467c06ed57d706a9a3dd141b9d'}, 'tests/test_first5_candidate.py': {'data': '', 'sha256': 'f7356efbe9e5b8e79cc1265f38dd069327a48763d157f6defe2633b6b5aced86'}}
R.mkdir(exist_ok=False);(R/'tests').mkdir()
for name,item in files.items():
 raw=base64.b64decode(item['data']);assert hashlib.sha256(raw).hexdigest()==item['sha256']
 with (R/name).open('xb')as f:f.write(raw);f.flush();os.fsync(f.fileno())
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONPATH=str(R)+':'+str(S/'repo'),PYTHONDONTWRITEBYTECODE='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1');env.pop('PYTHONOPTIMIZE',None)
t=time.monotonic();r=subprocess.run([str(S/'env/bin/python'),'-B','-m','unittest','discover','-s',str(R/'tests'),'-v'],cwd=S/'repo',env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);log=r.stdout
with (R/'actual-linux-tests.log').open('xb')as f:f.write(log)
assert r.returncode==0 and b'Ran 16 tests' in log and b'\nOK\n' in log and b'skipped=' not in log
record=dict(status='ACTUAL_LINUX_FIRST5_BEHAVIOR_V2_CODE_TESTS_NOT_NATIVE',source_commit='90755a561abd239fbb23882939410e643bb913ae',root=str(R),host=os.uname().nodename,tests_passed=16,tests_skipped=0,exit_code=r.returncode,elapsed_seconds=time.monotonic()-t,raw_log_sha256=hashlib.sha256(log).hexdigest(),files_sha256={k:v['sha256']for k,v in files.items()},native_acceptance=False,production_release=False)
with (R/'actual-linux-tests.json').open('x')as f:json.dump(record,f,indent=2);f.flush();os.fsync(f.fileno())
print(json.dumps(record))
